def lcm(a, b):
    # Find the GCD of a and b using the Euclidean algorithm
    def gcd(a, b):
        while b != 0:
            a, b = b, a % b
        return a

    # Calculate LCM using the formula: LCM(a, b) = |a*b| / GCD(a, b)
    return abs(a * b) // gcd(a, b)

